diff --git a/repro/repro.js b/repro/repro.js
new file mode 100644
index 0000000..d29633a
--- /dev/null
+++ b/repro/repro.js
@@ -0,0 +1,53 @@
+"use strict";
+
+/*
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ * Run on Windows directly, or anywhere with:
+ *   node -r ./repro/simulate-windows.js repro/repro.js
+ */
+const path = require("node:path");
+const { ESLint, Linter } = require("../lib/api");
+
+const cwd = process.cwd();
+const config = { rules: { "no-undef": "error" } };
+
+const sameDriveOutside = path.resolve(cwd, "..", "Other", "foo.js"); // e.g. C:\Other\foo.js
+const otherDrive = `${cwd[0] === "F" ? "G" : "F"}:\\foo.js`; // e.g. F:\foo.js
+
+console.log(`platform path flavor: ${path === path.win32 ? "win32" : "posix"}, cwd: ${cwd}`);
+console.log(`path.relative(cwd, ${sameDriveOutside}) = ${JSON.stringify(path.relative(cwd, sameDriveOutside))}`);
+console.log(`path.relative(cwd, ${otherDrive})        = ${JSON.stringify(path.relative(cwd, otherDrive))}`);
+
+(async () => {
+    let failed = false;
+
+    // 1) Linter: a file outside the base path should get "No matching configuration".
+    const linter = new Linter({ configType: "flat" });
+
+    for (const filename of [sameDriveOutside, otherDrive]) {
+        const messages = linter.verify("foo()", config, filename);
+        const ignored = messages.length === 1 && messages[0].ruleId === null &&
+            messages[0].message.startsWith("No matching configuration found");
+
+        console.log(`\n[Linter] ${filename}: ${ignored ? "IGNORED (expected)" : "LINTED (BUG)"}`);
+        console.log(JSON.stringify(messages.map(m => ({ ruleId: m.ruleId, message: m.message }))));
+        failed ||= !ignored;
+    }
+
+    // 2) ESLint (same code path as `npx eslint --no-config-lookup F:\foo.js`):
+    //    the result should be a "File ignored because outside of base path." warning.
+    const eslint = new ESLint({ cwd, overrideConfigFile: true, overrideConfig: config });
+
+    for (const filePath of [sameDriveOutside, otherDrive]) {
+        const [result] = await eslint.lintText("foo();\n", { filePath, warnIgnored: true });
+        const ignored = result.messages.length === 1 && result.messages[0].ruleId === null &&
+            /^File ignored/u.test(result.messages[0].message);
+
+        console.log(`\n[ESLint] ${filePath}: ${ignored ? "IGNORED (expected)" : "LINTED (BUG)"}`);
+        console.log(JSON.stringify(result.messages.map(m => ({ ruleId: m.ruleId, message: m.message }))));
+        failed ||= !ignored;
+    }
+
+    console.log(failed ? "\nBUG REPRODUCED: file on another drive was not ignored." : "\nNo bug: all files outside base path were ignored.");
+    process.exitCode = failed ? 1 : 0;
+})();
diff --git a/repro/simulate-windows.js b/repro/simulate-windows.js
new file mode 100644
index 0000000..d04bb3d
--- /dev/null
+++ b/repro/simulate-windows.js
@@ -0,0 +1,23 @@
+"use strict";
+
+/*
+ * Preload (`node -r`) that makes Node behave like Windows for path handling:
+ * every require("path") / require("node:path") returns path.win32, and
+ * process.cwd() returns a directory on drive C:. This lets the Windows-only
+ * cross-drive bug be reproduced on Linux/macOS.
+ */
+const Module = require("node:module");
+const path = require("node:path");
+
+const originalLoad = Module._load;
+
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") {
+        return path.win32;
+    }
+    return originalLoad.call(this, request, ...rest);
+};
+
+const FAKE_CWD = process.env.FAKE_CWD || "C:\\Project";
+
+process.cwd = () => FAKE_CWD;
